test "AsmJit a64 assembler tests (2400..2800)" {
    var fails: u32 = 0;
    fails += check(0x6E205841, .@"mvn", &.{ a64.vec(1, .a16b), a64.vec(2, .a16b) }, "4158206E mvn_(v1.b16(), v2.b16())");
